#!/usr/bin/env python3
"""
Post-build fixes.

index.html and the marketing pages are GENERATED by build_pages.py from
Glovels_Content_Master.xlsx. Editing them by hand works until the next rebuild,
which silently throws the edit away. So every hand fix lives here instead, and
this script is run after a rebuild.

Every patch is idempotent: it checks for its own result first, so running this
twice changes nothing and running it on an unpatched rebuild fixes it again.

    python3 apply_fixes.py
"""

import os
import pathlib
import re
import hashlib
import sys

import content_client

HERE = pathlib.Path(__file__).parent
applied, skipped = [], []


def write(path, text):
    """
    Write, or do not write at all.

    `Path.write_text` truncates the file and then writes. If anything goes wrong
    in between — and it did once, leaving index.html at zero bytes — the original
    is gone and there is nothing to fall back on. So: refuse anything
    suspiciously short, write to a temp file, fsync it, and rename. A rename is
    atomic, so the file on disk is either the old one or the new one.
    """
    if len(text) < 1000:
        sys.exit(f"REFUSED to write {path.name}: the result is only {len(text)} bytes. "
                 f"That is a bug in the patch, not a small file.")
    tmp = path.with_suffix(path.suffix + ".tmp")
    with open(tmp, "w", encoding="utf-8") as fh:
        fh.write(text)
        fh.flush()
        os.fsync(fh.fileno())
    os.replace(tmp, path)


def patch(fname, name, old, new, count=1, marker=None):
    """
    Literal replacement, skipped when it has already been applied.

    `marker` is how "already applied" is decided when a LATER patch edits text
    that this one inserted — then `new` is no longer present verbatim even
    though the patch did run, and testing for `new` would wrongly re-run it and
    then fail on the missing anchor. Give such patches a short, unique string
    from the part no later patch touches.
    """
    p = HERE / fname
    t = p.read_text(encoding="utf-8")
    if (marker or new) in t:
        skipped.append(f"{fname}: {name}")
        return
    if old not in t:
        sys.exit(f"FAILED {fname}: {name}\n  anchor not found — the build output changed, "
                 f"re-check this patch before shipping")
    write(p, t.replace(old, new, count))
    applied.append(f"{fname}: {name}")


def patch_re(fname, name, pattern, new, present):
    p = HERE / fname
    t = p.read_text(encoding="utf-8")
    if present(t):
        skipped.append(f"{fname}: {name}")
        return
    t2, n = re.subn(pattern, new, t, count=1, flags=re.S)
    if not n:
        sys.exit(f"FAILED {fname}: {name} — pattern not found")
    write(p, t2)
    applied.append(f"{fname}: {name}")


