# Opened by double-clicking, on every page.
#
# The site uses clean addresses (/study-in-germany, not study-in-germany.html)
# and the portal talks to a server, so a file:// copy has broken links and a
# sign-in that cannot work. That is not obvious from the inside — the page
# looks fine — so it says so, once, at the top, and it cannot be missed.
# ---------------------------------------------------------------------------

FILE_BANNER = """<script>
/* GLOVELS-FILE-WARNING
   This runs at the end of <body>, so document.body already exists. It waited
   for DOMContentLoaded at first, which never arrived on pages where an earlier
   script had already thrown \\u2014 and a warning that only appears when nothing
   else is wrong is a warning that never appears. */
if (location.protocol === 'file:') {
  var b = document.createElement('div');
  b.style.cssText = 'position:fixed;left:0;right:0;top:0;z-index:99999;padding:13px 18px;' +
    'background:#7a2118;color:#fff;font:600 13.5px/1.55 system-ui,-apple-system,sans-serif;' +
    'text-align:center;box-shadow:0 4px 18px rgba(0,0,0,.25)';
  b.innerHTML = '<b>This page was opened straight from the folder.</b> Links and sign-in ' +
    'will not work. Close this tab, double-click <b>start.command</b>, and use the address ' +
    'it opens \\u2014 <b>http://localhost:8080</b>';
  document.body.appendChild(b);
  document.body.style.paddingTop = b.offsetHeight + 'px';
}
</script>
"""


def banner_everywhere():
    n = 0
    for f in sorted(list(HERE.glob("*.html")) + list((HERE / "post").glob("*.html"))):
        t = f.read_text(encoding="utf-8")
        # A marker unique to the banner. "opened straight from the folder" is
        # not: the login page says the same words in its error message, so
        # login.html — the one page people actually double-click — was the one
        # page that never got the banner.
        if "GLOVELS-FILE-WARNING" in t or "</body>" not in t:
            continue
        write(f, t.replace("</body>", FILE_BANNER + "</body>", 1))
        n += 1
    if n:
        applied.append(f"{n} page(s): a warning when the page is opened as a file")
    else:
        skipped.append("every page: a warning when the page is opened as a file")


banner_everywhere()


# ---------------------------------------------------------------------------
# The notifications bell did nothing.
#
# It had an aria-label, a hover state and an unread dot, and no handler at all —
# the one button on the dashboard that was pure decoration. Everything it needs
# is already in /api/state: unread messages, document statuses, the shortlist
# with its deadlines. So it opens a panel and says what is waiting.
# ---------------------------------------------------------------------------

BELL = """
/* The bell. It reads /api/state, which the dashboard has already fetched, and
   says what is actually waiting on this student — unread messages, documents
   that were sent back, the next deadline. The dot appears only when there is
   something, because a dot that is always on is a dot nobody looks at. */
(function () {
  var bell = document.getElementById('bell');
  if (!bell) return;

  var panel = null;
  var esc = function (t) {
    return String(t == null ? '' : t).replace(/[&<>"]/g, function (c) {
      return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}[c];
    });
  };

  function items(st) {
    var out = [];
    if (st.unread) {
      out.push({ href: 'messages.html', what: st.unread + ' new message'
        + (st.unread === 1 ? '' : 's') + ' from your counsellor', urgent: true });
    }
    Object.keys(st.docs || {}).forEach(function (k) {
      var d = st.docs[k];
      if (d.status === 'no') {
        out.push({ href: 'documents.html',
          what: esc(d.file) + ' was sent back — it needs uploading again', urgent: true });
      }
    });
    var wait = Object.keys(st.docs || {}).filter(function (k) {
      return st.docs[k].status === 'wait';
    }).length;
    if (wait) {
      out.push({ href: 'documents.html',
        what: wait + ' document' + (wait === 1 ? ' is' : 's are') + ' with your counsellor to check' });
    }

    /* The nearest deadline that has not gone. The pages roll a past deadline
       forward a year so nothing reads as expired; do the same here, or the
       soonest thing showing is always the one furthest in the past. */
    var now = new Date(), soonest = null;
    (st.shortlist || []).forEach(function (p) {
      (p.intakes || []).forEach(function (i) {
        var d = new Date(i.deadline);
        if (isNaN(d)) return;
        while (d < now) d.setFullYear(d.getFullYear() + 1);
        if (!soonest || d < soonest.at) soonest = { at: d, p: p };
      });
    });
    if (soonest) {
      var days = Math.round((soonest.at - now) / 86400000);
      out.push({ href: 'universities.html',
        what: esc(soonest.p.university) + ' closes in ' + days + ' day' + (days === 1 ? '' : 's'),
        urgent: days <= 30 });
    }
    if (!(st.profile && Object.keys(st.profile).length)) {
      out.push({ href: 'profile.html', what: 'Your profile is empty — it is what the shortlist is built from' });
    }
    return out;
  }

  function draw(list) {
    if (panel) panel.remove();
    panel = document.createElement('div');
    panel.style.cssText = 'position:absolute;top:46px;right:0;z-index:300;width:min(360px,86vw);'
      + 'background:#fff;border:1px solid #e6e9ee;border-radius:14px;padding:8px;'
      + 'box-shadow:0 18px 44px rgba(11,30,49,.18);text-align:left';
    panel.innerHTML = list.length
      ? list.map(function (i) {
          return '<a href="' + i.href + '" style="display:block;padding:11px 13px;border-radius:10px;'
            + 'font:600 13px/1.5 system-ui,sans-serif;text-decoration:none;text-align:left;'
            + 'color:' + (i.urgent ? '#7a2118' : '#1b3a5c') + '">' + i.what + '</a>';
        }).join('')
      : '<p style="margin:0;padding:16px 14px;font:500 13px/1.55 system-ui,sans-serif;color:#6b7684">'
        + 'Nothing needs you right now.</p>';
    bell.style.position = 'relative';
    bell.appendChild(panel);
  }

  bell.addEventListener('click', function (e) {
    e.preventDefault();
    e.stopPropagation();
    if (panel) { panel.remove(); panel = null; return; }
    draw([{ href: '#', what: 'Looking…' }]);
    fetch('/api/state', { credentials: 'same-origin' })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (st) { if (st) draw(items(st)); })
      .catch(function () { draw([]); });
  });
  document.addEventListener('click', function () {
    if (panel) { panel.remove(); panel = null; }
  });

  /* The dot, from the same source, once, on load. */
  fetch('/api/state', { credentials: 'same-origin' })
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (st) {
      var dot = bell.querySelector('.dot');
      if (!dot || !st) return;
      /* The `hidden` ATTRIBUTE, not style.display. The markup ships the dot
         with hidden on it, and hidden beats an inline display:'' — setting the
         style looked right in the code and did nothing on the screen. */
      dot.hidden = !items(st).some(function (i) { return i.urgent; });
    })
    .catch(function () {});
}());
"""

